parameters.jsCode:
const ts_start_ms = Date.now();
const trace_id =
`trc_${ts_start_ms}_${Math.floor(Math.random() *
100000)}`;
const ts = new Date(ts_start_ms).toISOString();

// n8n Webhook node wraps the full request:
//   $json.headers  — HTTP headers
//   $json.body     — POST JSON body
//   $json.query    — GET query string params
//   $json.webhookUrl — the webhook URL itself (provided by n8n)
const headers = $json.headers || {};
const body    = $json.body   || {};
const query   = $json.query  || {};

// message_source: WH = webhook, TG = Telegram (future)
// Determined by the presence of webhookUrl in the n8n data
const webhookUrlN8n = $json.webhookUrl || '';
const message_source = webhookUrlN8n ? 'WH' : '';

const executionMode = $json.executionMode || '';

// Keep the UI operation ID separate from the HTTP proxy's request ID.
// An intermediary can assign a new header ID when forwarding the same payload again.
const client_request_id = body.requestId || query.requestId || '';
const client_timestamp = body.timestamp || query.timestamp || '';
const proxy_request_id = headers['x-request-id'] || '';
const request_id = client_request_id || proxy_request_id;

// message and sessionId come from body (POST) or query string (GET)
const user_message_text = body.message || body.user_message_text
                       || query.message || query.user_message_text || '';
const sessionId = body.sessionId || query.sessionId || '';

return [{ json: {
 sessionId,
 message_source,
 executionMode,
 user_message_text,
 trace_id,
 ts,
 ts_start_ms,
 request_id,
 client_request_id,
 client_timestamp,
 proxy_request_id } }];

const items = $input.all();

const nodeSession = $('Get sessionId').first().json;
const user_message_text = nodeSession['user_message_text'];
const message_source    = nodeSession['message_source'];
const sessionId         = nodeSession['sessionId'];

const byKey = new Map();
for (const it of items) {
  const keyRaw = it.json.field_key;
  if (keyRaw == null) continue;
  const key = String(keyRaw).trim();
  if (!key) continue;
  const tsRaw = it.json.updatedAt ?? it.json.createdAt ?? null;
  const tsMs = tsRaw ? new Date(tsRaw).getTime() : 0;
  const prev = byKey.get(key);
  if (!prev || tsMs > prev.updatedAtMs) {
    byKey.set(key, {
      value: it.json.field_value ?? "",
      updatedAtMs: Number.isFinite(tsMs) ? tsMs : 0,
    });
  }
}

const chat_history = {};
for (const [key, rec] of byKey.entries()) {
  chat_history[key] = String(rec.value ?? "");
}

const ts_start_ms = Date.now();
const trace_id = `trc_${ts_start_ms}_${Math.floor(Math.random() * 100000)}`;
const ts = new Date(ts_start_ms).toISOString();

return [{ json: { 
  chat_history, 
  sessionId : sessionId, 
  user_message_text,
  message_source,
  trace_id, ts, ts_start_ms } }];

const DEBUG_ENABLED = true;
const TELEGRAM_SOFT_LIMIT = 3500;
const DEBUG_JSON_MAX_LEN = 1800;
const DEBUG_JSON_MID_LEN = 1200;
const DEBUG_JSON_MIN_LEN = 700;

// ─── Debug section order ───────────────────────────────────────────────────────
// Remove or reorder entries to control what appears and in what order.
// Available: "agent_logic" | "tools_used" | "chat_history" | "latency" | "errors"
const DEBUG_SECTIONS_ORDER = [
  "chat_history",
  "tools_used",
  "agent_logic",
  "latency",
];

// ─── HTML utils ───────────────────────────────────────────────────────────────

function escHtml(s) {
  return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function sanitizeTelegramHtml(input) {
  const allowedTags = [];
  const protected_ = String(input ?? "").replace(/<\/?(b|i|u|code|pre)>|<a\b[^>]*>|<\/a>/gi, (m) => {
    allowedTags.push(m);
    return `___TG_${allowedTags.length - 1}___`;
  });
  let out = escHtml(protected_);
  allowedTags.forEach((tag, i) => { out = out.replace(`___TG_${i}___`, tag); });
  return out;
}

function safeStringify(v) {
  try { return JSON.stringify(v, null, 2); }
  catch (e) { return `[stringify_error] ${e}\n\n${v}`; }
}

function shortenText(text, maxLen, suffix = "\n... [truncated]") {
  const s = String(text ?? "");
  if (!maxLen || s.length <= maxLen) return s;
  return s.slice(0, Math.max(0, maxLen - suffix.length)) + suffix;
}

function withFormat(title, value, maxLen = 0) {
  const text = typeof value === "string" ? value : safeStringify(value);
  const shortened = maxLen > 0 ? shortenText(text, maxLen) : text;
  const titlePart = title ? `<b>${escHtml(title)}</b>\n` : "";
  return `${titlePart}<code>${escHtml(shortened)}</code>`;
}

// ─── JSON utils ───────────────────────────────────────────────────────────────

function parseJsonMaybe(value) {
  if (value == null || typeof value !== "string") return value ?? null;
  try { return JSON.parse(value.trim()); } catch { return null; }
}

// ─── Intermediate steps ───────────────────────────────────────────────────────

function buildStepsSummary(steps) {
  if (!steps.length) return "No intermediate steps";
  const seen = new Set();
  const lines = [];
  for (const step of steps) {
    const callId = step?.action?.toolCallId || '';
    const key = callId || `step_${lines.length}`;
    if (seen.has(key)) continue;
    seen.add(key);

    const toolCall = step?.action?.messageLog?.[0]?.kwargs?.tool_calls?.[0];
    const toolName = toolCall?.name || step?.action?.tool || "Unknown Tool";
    const args = Object.fromEntries(
      Object.entries(toolCall?.args || {}).filter(([k]) => k !== "id")
    );
    lines.push(`${lines.length + 1}. tool=${toolName} | args=${JSON.stringify(args)}`);
  }
  return lines.join("\n");
}

// ─── Parse model output ───────────────────────────────────────────────────────

const raw = String($json.output ?? "").trim();
const agentError = $json.error ? String($json.error).trim() : null;
let obj = null, parse_error = "", schema_warning = "", reply_html = "", agent_logic = "", body = "", response_type = "text";

if (agentError) {
  response_type = "agent_error";
  body = sanitizeTelegramHtml(agentError);
} else if (!raw) {
  response_type = "empty";
  body = "<b>Ошибка</b>\n\nПустой ответ от модели.";
} else {
  const first = raw.indexOf("{"), last = raw.lastIndexOf("}");
  const jsonText = first !== -1 && last > first ? raw.slice(first, last + 1) : "";

  if (!jsonText) {
    response_type = "text";
    body = sanitizeTelegramHtml(raw);
  } else {
    try {
      obj = JSON.parse(jsonText);
      response_type = "json";
      reply_html = String(obj.reply_html ?? "").trim();
      body = reply_html ? sanitizeTelegramHtml(reply_html) : (schema_warning = "reply_html_empty", sanitizeTelegramHtml(raw));
      agent_logic = sanitizeTelegramHtml(String(obj.agent_logic ?? "").trim());
    } catch (e) {
      response_type = "json_parse_failed";
      parse_error = String(e);
      body = sanitizeTelegramHtml(raw);
    }
  }
}

// ─── Metrics ──────────────────────────────────────────────────────────────────

const chatMemory = $('Get sessionId').first().json;
const now = Date.now();
const latency_ms = Math.max(0, now - Number(chatMemory.ts_start_ms || now));
const intermediateSteps = (() => { const p = parseJsonMaybe($json.intermediateSteps); return Array.isArray(p) ? p : []; })();
const intermediate_steps_summary = buildStepsSummary(intermediateSteps);
const chatHistory = $('JSON Chat Memory').first().json.chat_history || {};
const success = response_type === "json" && !parse_error && Boolean(reply_html);
const is_agent_error = response_type === "agent_error";

const isWebhook = String(chatMemory.message_source ?? $json.message_source ?? "").toUpperCase() === "WH";

// ─── Build functions ──────────────────────────────────────────────────────────

function withDebugFormat(title, value, maxLen = 0) {
  const text = typeof value === "string" ? value : safeStringify(value);
  const shortened = maxLen > 0 ? shortenText(text, maxLen) : text;
  const titlePart = title ? `<b>${escHtml(title)}</b>\n` : "";
  return `${titlePart}<code>${escHtml(shortened)}</code>`;
}

// Debug-only section (без body) — используется для full_debug (WH) и inline TG
function buildDebugSection(maxLen = 0, forTg = false) {
  if (!DEBUG_ENABLED) return "";
  const noInfoTag = (text) => `<code>${text}</code>`;
  const blocks = [];

  if (parse_error)    blocks.push(withDebugFormat("[debug] parse_error", parse_error));
  if (schema_warning) blocks.push(withDebugFormat("[debug] schema_warning", schema_warning));

  for (const section of DEBUG_SECTIONS_ORDER) {
    if (section === "agent_logic") {
      blocks.push(withDebugFormat("LLM Logic", agent_logic, maxLen));

    } else if (section === "tools_used") {
      if (intermediateSteps.length > 0) {
        const stepsText = maxLen > 0 ? shortenText(intermediate_steps_summary, maxLen) : intermediate_steps_summary;
        blocks.push(`<b>Agent Tools used</b>\n<code>${escHtml(stepsText)}</code>`);
      } else {
        blocks.push(`<b>Agent Tools used</b>\n${noInfoTag("No intermediate steps")}`);
      }

    } else if (section === "chat_history") {
      if (Object.keys(chatHistory).length > 0) {
        blocks.push(withDebugFormat("Agent Chat History for LLM", chatHistory, maxLen));
      } else {
        blocks.push(`<b>Agent Chat History for LLM</b>\n${noInfoTag("No chat history")}`);
      }

    } else if (section === "latency") {
      const latencyStr = latency_ms < 1000
        ? `${latency_ms} ms`
        : `${(latency_ms / 1000).toFixed(1)} s`;
      blocks.push(`<b>Latency</b>\n<code>${latencyStr}</code>`);
    }
  }

  return blocks.filter(Boolean).join("\n\n");
}

// TG: body + debug inline, с каскадным сокращением
function buildTgOutput(maxLen = 0, includeDebug = true) {
  if (!includeDebug || !DEBUG_ENABLED) return body;
  return [body, buildDebugSection(maxLen, true)].filter(Boolean).join("\n\n");
}

// ─── Compute outputs ──────────────────────────────────────────────────────────

let output_clean, full_debug;

if (is_agent_error) {
  output_clean = "";
  full_debug = "";
} else if (isWebhook) {
  // WH: output_clean = только ответ модели; full_debug = отдельный debug-блок
  output_clean = body;
  full_debug = buildDebugSection(0, false);
} else {
  // TG: output_clean = body + debug inline, каскадное сокращение
  const candidates = [
    [DEBUG_JSON_MAX_LEN, true],
    [DEBUG_JSON_MID_LEN, true],
    [DEBUG_JSON_MIN_LEN, true],
    [0, false],
    null,
  ];
  output_clean = candidates.reduce((acc, p) =>
    acc.length <= TELEGRAM_SOFT_LIMIT ? acc : (p ? buildTgOutput(...p) : body),
    buildTgOutput(DEBUG_JSON_MAX_LEN, true)
  );
  full_debug = "";
}

// ─── Return ───────────────────────────────────────────────────────────────────

const output_short = shortenText(output_clean, 300);

return [{
  json: {
    ...$json,
    user_message_text: chatMemory.user_message_text,
    sessionId: chatMemory.sessionId,
    output_short,
    output_clean,
    full_debug,
    latency_ms,
    intermediate_steps_summary,
    chat_history: chatHistory,
    is_agent_error,
    success,
    agent_logic,
    parsed_object: obj,
    parse_error,
    schema_warning,
    response_type,
  }
}];

const rows = $input.all();
const agentResponse = $('AI Agent Output Parser').first().json;

function escHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

// При повторяющихся field_key берём последнюю запись
const byKey = new Map();

for (const item of rows) {
  const row = item.json ?? {};
  if (row.field_key == null) continue;

  const key = String(row.field_key).trim();
  if (!key || ['__proto__', 'constructor', 'prototype'].includes(key)) {
    continue;
  }

  const rawTime = row.updatedAt ?? row.createdAt;
  const parsedTime = rawTime ? Date.parse(rawTime) : 0;
  const timestamp = Number.isFinite(parsedTime) ? parsedTime : 0;
  const previous = byKey.get(key);

  if (!previous || timestamp > previous.timestamp) {
    byKey.set(key, {
      value: String(row.field_value ?? ''),
      timestamp,
    });
  }
}

// Формируем словарь
const last_chat_history = {};

for (const [key, record] of byKey) {
  last_chat_history[key] = record.value;
}

// Добавляем новый раздел отладки
const historyDebug =
  '<b>Last Chat History for Next Request</b>\n' +
  (Object.keys(last_chat_history).length
    ? `<code>${escHtml(JSON.stringify(last_chat_history, null, 2))}</code>`
    : '<code>No chat history</code>');

const full_debug = [
  String(agentResponse.full_debug ?? '').trim(),
  historyDebug,
].filter(Boolean).join('\n\n');

// Сохраняем все поля ответа AI Agent Output Parser
return [{
  json: {
    ...agentResponse,
    last_chat_history,
    full_debug,
  },
}];
